pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        // Precondition: initialize the contract so that SetMinSum is intended to be locked
        c.Initialized();

        // Record the MinSum after setting it once
        c.SetMinSum(val1);
        uint256 firstMinSum = c.MinSum();

        // A re-entrant attacker that calls SetMinSum(val2) during a fallback
        // We need an adversarial contract that re-enters SetMinSum
        // Deploy attacker with reference to c and val2
        ReEntrantAttacker attacker = new ReEntrantAttacker(c, val2);

        // The attacker calls SetMinSum, which during its execution will trigger a re-entrant call via the attacker's receive
        // We need to send Ether to trigger receive/fallback. The original SetMinSum is not payable, so we cannot use msg.value.
        // Instead, we make the attacker's function call SetMinSum and re-enter from within that call.
        // The attacker will call SetMinSum(val1), and inside that call, before the first call completes,
        // call SetMinSum(val2) again, which is possible because the buggy version lacks nonReentrant lock.
        vm.prank(address(attacker));
        attacker.attack();

        uint256 finalMinSum = c.MinSum();
        // For the reference (correct) contract, SetMinSum is nonReentrant, so the re-entrant call fails
        // and MinSum remains firstMinSum. For the buggy contract, the re-entrant SetMinSum(val2) succeeds,
        // changing MinSum to val2.
        // The universal rule: after the attack, MinSum should equal firstMinSum (the value set by the first call).
        assertTrue(finalMinSum == firstMinSum);
    }
}

contract ReEntrantAttacker {
    C public target;
    uint256 public newVal;
    bool private attacking;

    constructor(C _target, uint256 _newVal) {
        target = _target;
        newVal = _newVal;
    }

    function attack() external {
        // Start the first call to SetMinSum
        target.SetMinSum(0); // value doesn't matter; will be overwritten by re-entrant call if possible
    }

    fallback() external payable {
        // Re-enter SetMinSum with newVal
        if (!attacking) {
            attacking = true;
            target.SetMinSum(newVal);
        }
    }
}

