pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialMinSum, uint256 changedMinSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(initialMinSum != changedMinSum);
        vm.assume(collectAmount > 0);
        vm.assume(depositAmount >= collectAmount);
        vm.assume(initialMinSum > 0);
        vm.assume(collectAmount >= initialMinSum && collectAmount >= changedMinSum);

        // 1. Setup C and adversarial reentrant attacker
        ReentrantAttacker attacker = new ReentrantAttacker();

        // 2. Set LogFile so Collect does not revert on Log calls
        c.SetLogFile(address(0xdead));
        c.SetMinSum(initialMinSum);
        c.Initialized();

        // 3. Fund attacker so it can deposit and later collect
        vm.deal(address(attacker), depositAmount);
        attacker.depositToC{value: depositAmount}(address(c));

        // 4. Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + 1 days);

        // 5. Perform reentrant attack: attacker collects and reenters to change MinSum
        attacker.collectAndReenter(address(c), collectAmount, changedMinSum);

        // 6. After all calls, MinSum must remain initialMinSum
        assertEq(c.MinSum(), initialMinSum);
    }
}

contract ReentrantAttacker {
    bool private reentered;
    uint256 private targetAmount;
    uint256 private newMinSum;

    function depositToC(address payable target) external payable {
        C(target).Put{value: msg.value}(0);
    }

    function collectAndReenter(address payable target, uint256 amount, uint256 _newMinSum) external {
        reentered = false;
        targetAmount = amount;
        newMinSum = _newMinSum;
        C(target).Collect(amount);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reenter via unprotected SetMinSum to change MinSum mid-Collect
            C(msg.sender).SetMinSum(newMinSum);
        }
    }
}

