pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val1, uint256 val2, bool reenter) public {
        // Restrict to admissible domain: MinSum is a uint, so any values are valid.
        // Deploy a re-entrant attacker helper.
        ReentrantAttacker attacker = new ReentrantAttacker();
        attacker.setTarget(address(c));

        // Deploy Log contract (needed by Initialized)
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // The attacker initiates the scenario: it calls SetMinSum with val1.
        // In the buggy mutant (no require(!locked_)), the attacker can re-enter during the first call
        // and set MinSum to val2, then the original call resumes and sets MinSum to val1.
        // In the reference, the reentrant call is blocked, so MinSum ends up as val1.
        attacker.setParams(val1, val2, reenter);

        // Drive through SetMinSum via attacker
        attacker.attack();

        // After the dust settles, we require that MinSum equals val1 (the value from the last call that actually executed).
        // In reference: only the outer call succeeds, MinSum = val1.
        // In mutant: both execute; if reenter, MinSum ends up as val1 (outer overwrites inner).
        // Wait – the bug difference: after a call to SetMinSum completes, MinSum differs.
        // Actually, in the mutant without require(!locked_), a reentrant call can set MinSum to val2,
        // and the outer call's val1 overwrites it, so MinSum = val1. That matches reference.
        // But the property says: after SetMinSum, MinSum = _val of that call.
        // The mutant allows reentrant calls, which can leave the contract in a state where a subsequent
        // call to Initialized changes the behavior of future calls? No.

        // Alternative approach: The reentrant call itself is a call to SetMinSum.
        // If reenter is true, the attacker's receive() calls SetMinSum with val2.
        // In reference, require(!locked_) blocks it; in mutant, it succeeds.
        // After the dust settles, we can check that the last successful SetMinSum value is reflected.
        // But we need to know which call happened last. The mutant executes inner then outer.
        // So MinSum = val1 regardless. That doesn't differentiate.

        // Proper difference: In reference, SetMinSum is protected by nonReentrant_ modifier.
        // Since require(!locked_) is removed, reentrant calls can happen.
        // The difference: the reference contract never reverts due to reentrancy guard;
        // the mutant allows reentrancy, which can lead to state corruption when combined
        // with other functions? But the problem says: "P and M differ in this way:
        // after a call to SetMinSum(...) completes, the value of state variable MinSum differs".
        // So we need a scenario where a single call to SetMinSum causes a re-entrant call
        // that changes state in a way that the outer call does not expect.

        // Since the nonReentrant_ modifier is on SetMinSum, and the only state change in SetMinSum is MinSum = _val,
        // a re-entrant call to SetMinSum would change MinSum to a different value, and then the outer call
        // overwrites it. So MinSum ends up as the outer call's parameter. That's the same as reference.
        // So how can MinSum differ? In the reference, the reentrant call reverts due to require(!locked_).
        // Therefore, the reference's MinSum after the outer call = val1.
        // In the mutant, the inner call succeeds, so MinSum becomes val2, then outer call sets it to val1.
        // So both end up with MinSum = val1. Not different.

        // Wait: what if the inner call is to Initialized? That sets intitalized = true.
        // Then the outer call checks if(intitalized) revert(). So the outer call would revert.
        // In mutant: attacker calls SetMinSum, which calls back to attacker, which calls Initialized.
        // Then Initialized sets intitalized = true. Outer call resumes, sees intitalized true, reverts.
        // So MinSum remains val2 (from inner call). In reference: inner call to Initialized would revert
        // due to require(!locked_), so intitalized stays false, outer call succeeds, MinSum = val1.
        // That would make MinSum differ.
        // That's the property.
    }
}

