import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 initVal, uint8 secondVal) public {
        // The domain: any uint8 values are admissible; SetMinSum expects a uint.
        // Step 1: initialize the contract
        c.Initialized();

        // Step 2: first call to SetMinSum; for the reference this succeeds and sets MinSum,
        // after which the modifier lock is released. For the buggy version, the lock is
        // never acquired so it also succeeds.
        c.SetMinSum(initVal);

        // Step 3: second call to SetMinSum.
        // Reference: locked_ is false, so require(!locked_) passes, then locked_ = true,
        // but intitalized is true so revert(). The call fails.
        // Buggy: locked_ = false in modifier, require(!locked_) always passes,
        // but intitalized is true so revert() — this would fail in both.
        // WAIT: actually both revert on second call because intitalized is true.
        // So we cannot simply call SetMinSum twice after Initialized().
        // We need a scenario where the modifier's locked_ state matters:
        // a reentrant call that calls SetMinSum again while the first call is still
        // executing (inside the _ placeholder). The bug locks_ = false so the reentrant
        // call's require(!locked_) passes, allowing it to execute. In the reference,
        // locked_ = true, so the reentrant call fails the require.
        // But the fuzzer cannot synthesize a reentrant caller from an address parameter.
        // We must deploy a helper reentrant attacker.
    }
}

contract ReentrantAttacker {
    C target;
    bool done;
    constructor(address _target) { target = C(_target); }
    function attack(uint val) external {
        // We need to be inside SetMinSum; SetMinSum is nonReentrant_ and has no callbacks.
        // There is no low-level call to an external address in SetMinSum, so reentrancy
        // cannot occur through SetMinSum alone.
        // The difference is modifier nonReentrant_() { locked_ = true; vs locked_ = false; }
        // This only affects whether reentrant calls are blocked. If there is no way to
        // call back into the contract during execution of a function using the modifier,
        // the lock state doesn't matter. So we need a function that uses the modifier
        // and makes an external call that can re-enter.
        // Check the contract C: Put, Collect, SetMinSum, SetLogFile, Initialized all use
        // nonReentrant_. Put and Collect make external calls (to msg.sender in Collect,
        // and Log.AddMessage). Log.AddMessage is an external call to a LogFile contract.
        // If we control the LogFile contract, we can make its AddMessage function call
        // back into C, triggering reentrancy. The LogFile address is set via SetLogFile,
        // which itself uses nonReentrant_. But initial SetLogFile is before initialization?
        // Actually, SetLogFile reverts if intitalized is true, so it must be called before
        // Initialized. We can do that. Then we can call Put, which calls Log.AddMessage,
        // and our malicious LogFile calls SetMinSum reentrantly. In the reference,
        // the lock prevents this reentrant SetMinSum; in the buggy, it succeeds, changing MinSum.
        // This satisfies: after the transaction, MinSum differs.
        // However, the test must observe c only through its public surface, and the assertion
        // must be about MinSum after some sequence.
        // We can use a helper that is both the LogFile and the reentrant caller.
    }
}

